sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    var chartEnd = null;

    $scope.anoSelecionadoEnd = "";
    $scope.exibirGraficoEnd = false;

    var coresEnd = {
        apurado: '#a7b9e8'
    };

    // Carrega dados do servidor com filtro de ano
    function carregarDadosEndFiltrado() {
        var filtros = {
            ano: $scope.anoSelecionadoEnd || ""
        };
        $scope.server.get(filtros).then(function(response) {
            var dados = response.data.dadosGraficoEnd || [];
            var anosDisponiveis = response.data.anos || [];

            $timeout(function() {
                montarGraficoEnd(dados, anosDisponiveis);
            });
        });
    }

    // Escuta o evento do filtro de ano
    $rootScope.$on('anoSelecionado', function(event, ano) {
        $scope.anoSelecionadoEnd = ano;
        carregarDadosEndFiltrado();
    });

    // chamada inicial
    carregarDadosEndFiltrado();

    function montarGraficoEnd(listaDados, anosDisponiveis) {

        // anos presentes na série
        var anosPresentes = [];
        listaDados.forEach(function(item) {
            if (anosPresentes.indexOf(item.ano) === -1) {
                anosPresentes.push(item.ano);
            }
        });

        // ordena anos
        anosPresentes.sort(function(a, b) {
            return parseInt(a) - parseInt(b);
        });

        if (anosPresentes.length === 0) {
            if (chartEnd) {
                chartEnd.destroy();
                chartEnd = null;
            }
            $scope.exibirGraficoEnd = false;
            return;
        }
        $scope.exibirGraficoEnd = true;

        var isSingleYear = (anosPresentes.length === 1);

        // vetor de valores
        var dadosApurado = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseFloat(item.apurado) : null;
        });

        // min/max reais da série (em cima dos valores válidos)
        var valoresValidos = dadosApurado.filter(function(v) {
            return v !== null && !isNaN(v);
        });

        var minValor = Math.min.apply(null, valoresValidos);
        var maxValor = Math.max.apply(null, valoresValidos);

        var yMin, yMax;

        if (isSingleYear) {
            // um único ano: eixo começa em 0
            var v = valoresValidos[0]; // só tem um
            var paddingSingle = Math.abs(v) * 0.3; // 30% de folga

            if (v >= 0) {
                yMin = 0;
                yMax = v + paddingSingle;
            } else {
                yMax = 0;
                yMin = v - paddingSingle;
            }
        } else {
            // vários anos: eixo dinâmico normal
            if (minValor === maxValor) {
                if (minValor === 0) {
                    minValor = -1;
                    maxValor = 1;
                } else {
                    var paddingSame = Math.abs(minValor) * 0.3;
                    minValor = minValor - paddingSame;
                    maxValor = maxValor + paddingSame;
                }
            }

            var margem = (maxValor - minValor) * 0.1; // mais 10% de folga
            yMin = minValor - margem;
            yMax = maxValor + margem;
        }

        // unidade dinâmica para o gráfico inteiro
        var maxAbs = Math.max(Math.abs(yMin), Math.abs(yMax));
        var unidadeEscala = '';   // '', ' mil', ' mi', ' bi'
        var divisorEscala = 1;

        if (maxAbs >= 1e9) {
            unidadeEscala = ' bi';
            divisorEscala = 1e9;
        } else if (maxAbs >= 1e6) {
            unidadeEscala = ' mi';
            divisorEscala = 1e6;
        } else if (maxAbs >= 1e3) {
            unidadeEscala = ' mil';
            divisorEscala = 1e3;
        }

        var chartType = isSingleYear ? 'bar' : 'line';

        // dataset
        var datasets = [{
            label: 'Valor Apurado',
            data: dadosApurado,
            fill: !isSingleYear,                      // área só quando tem mais de um ano
            tension: isSingleYear ? 0 : 0.2,
            borderColor: '#a7b9e8',
            backgroundColor: isSingleYear
                ? '#a7b9e8'
                : 'rgba(75, 119, 191, 0.3)',
            borderWidth: isSingleYear ? 1 : 2,
            pointRadius: 0,
            pointHitRadius: 8,
            pointStyle: 'rect',
            pointBackgroundColor: '#a7b9e8',
            pointBorderColor: '#a7b9e8',
            pointBorderWidth: 0
        }];

        var ctx = document.getElementById('graficoCaixaLiquido').getContext('2d');

        if (chartEnd) {
            chartEnd.destroy();
            chartEnd = null;
        }

        chartEnd = new Chart(ctx, {
            type: chartType,
            data: {
                labels: anosPresentes,
                datasets: datasets
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                animation: {
                    duration: 700,
                    easing: 'easeInOutQuad'
                },
                scales: {
                    x: {
                        display: true,
                        title: { display: false },
                        offset: true,
                        grid: { offset: true },
                        ticks: {
                            color: '#0E2B69',
                            font: {
                                size: 16,
                                weight: 800,
                                family: 'Roboto Flex, sans-serif',
                                lineHeight: 1.8
                            },
                            padding: 6,
                            maxRotation: 0,
                            autoSkip: false
                        }
                    },
                    y: {
                        display: true,
                        position: 'right',
                        min: yMin,
                        max: yMax,
                        ticks: {
                            callback: function(value) {
                                var scaled = value / divisorEscala;
                                return scaled.toLocaleString('pt-BR', {
                                    minimumFractionDigits: 2,
                                    maximumFractionDigits: 2
                                }) + unidadeEscala;
                            },
                            color: '#0E2B69',
                            font: {
                                size: 14,
                                family: 'Roboto Flex, sans-serif'
                            }
                        },
                        grid: {
                            color: 'rgba(0,0,0,0.05)'
                        }
                    }
                },
                plugins: {
                    legend: {
                        display: true,
                        position: 'top',
                        labels: {
                            usePointStyle: true
                        }
                    },
                    tooltip: {
                        enabled: true,
                        callbacks: {
                            label: function(context) {
                                var value = context.raw || 0;
                                var scaled = value / divisorEscala;
                                return context.dataset.label + ': ' +
                                    scaled.toLocaleString('pt-BR', {
                                        minimumFractionDigits: 2,
                                        maximumFractionDigits: 2
                                    }) + unidadeEscala;
                            }
                        }
                    },
                    datalabels: {
                        display: isSingleYear,             // mostra valor só quando for barra
                        anchor: 'end',
                        align: 'end',
                        formatter: function(value) {
                            if (value === null || isNaN(value)) return '';
                            var scaled = value / divisorEscala;
                            return scaled.toLocaleString('pt-BR', {
                                minimumFractionDigits: 2,
                                maximumFractionDigits: 2
                            }) + unidadeEscala;
                        },
                        color: '#0E2B69',
                        font: {
                            weight: 'bold',
                            family: 'Roboto Flex, sans-serif'
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

.titleEnd{
   font-family: Roboto;
  font-weight: 500;
  font-style: Medium;
  font-size: 24px;
  leading-trim: NONE;
  line-height: 100%;
  letter-spacing: 0%;
	color:#021770;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};
    data.dadosGraficoEnd = [];
    data.anos = [];

    var anoFiltro = input.ano || "";

    // Anos disponíveis
    var grAnos = new GlideAggregate('x_sded9_portal_t_0_programa_de_ajuste_fiscal');
    grAnos.addAggregate('COUNT');
    grAnos.groupBy('u_ano');
    grAnos.orderBy('u_ano');
    grAnos.query();

    while (grAnos.next()) {
        data.anos.push(grAnos.getValue('u_ano').toString());
    }

    data.anos = Array.from(new Set(data.anos));
    data.anos.sort();

    // Dados do gráfico
    var grEnd = new GlideRecord('x_sded9_portal_t_0_programa_de_ajuste_fiscal');

    if (anoFiltro !== "" && anoFiltro.toLowerCase() !== "todos") {
        grEnd.addQuery('u_ano', anoFiltro);
    }

    grEnd.orderBy('u_ano');
    grEnd.query();

    var listaEnd = [];
    while (grEnd.next()) {
        var ano = grEnd.getValue('u_ano').toString();

        // TROCAR ESSE CAMPO PELO CERTO DO CAIXA LÍQUIDO
        var apurado = grEnd.getValue('valor_apurado_caixa_liquido') || '0';

        listaEnd.push({
            ano: ano,
            apurado: parseFloat(apurado)
        });
    }

    data.dadosGraficoEnd = listaEnd;
})();
